/** What a real job result may override on top of the fixture notation
 *  (score/jobResult.ts) — MusicXML itself stays fixture until the engine
 *  ships document bodies. */
export interface FixtureDocumentOverrides {
  /** Completed job's `scoreRevision`, when present. */
  readonly revisionId?: string;
  /** Review issues from the job result — `[]` honestly means "the engine
   *  found nothing to flag" (never fall back to fixture issues then). */
  readonly issues?: readonly ScoreReviewIssue[];
}

class FixtureScoreDocument implements ScoreDocumentPort {
  readonly revisionId: string;
  readonly meta: ScoreDocumentMeta;
  private readonly issues: readonly ScoreReviewIssue[];

  constructor(overrides?: FixtureDocumentOverrides) {
    const doc = parseScoreDoc(concertXml);
    const canonical = new Set(doc.notes.map((n) => n.canonicalId).filter(Boolean));
    this.revisionId = overrides?.revisionId ?? FIXTURE_REVISION;
    this.issues = overrides?.issues ?? FIXTURE_ISSUES;
    this.meta = {
      title: doc.title,
      tempoBpm: doc.tempoBpm,
      meter: doc.meter,
      keyFifths: doc.keyFifths,
      measureCount: doc.measureCount,
      noteCount: canonical.size,
    };
  }

  musicXml(view: PitchViewSetting): string {
    return view === "hornF" ? hornXml : concertXml;
  }

  reviewIssues(): readonly ScoreReviewIssue[] {
    return this.issues;
  }
}

/**
 * The deterministic score document used until the engine pipeline delivers
 * real `ScoreDocumentPort` data (UI-040+). Everything derived from it —
 * rendered pages, canonical ids, review markers — is byte-stable.
 *
 * `overrides` carries the UI-040 result handoff (score/jobResult.ts):
 * the job's `scoreRevision` and typed review issues flow through while the
 * notation body remains the committed fixture.
 */
export function createFixtureScoreDocument(
  overrides?: FixtureDocumentOverrides,
): ScoreDocumentPort {
  return new FixtureScoreDocument(overrides);
}

/**
 * Canonical-id rule tests (UI-030). Mirrors FND-001 / ids.py: every
 * `hs-sn-*` export id resolves to exactly one `sn-*` canonical id;
 * rests and random Verovio ids never do.
 */
import { describe, expect, it } from "vitest";
import {
  canonicalNoteIdFromMusicxml,
  isMusicxmlNoteId,
  isMusicxmlRestId,
  isReviewIssueId,
  isScoreNoteId,
  musicxmlNoteId,
} from "./ids";

describe("score ids", () => {
  it("recognizes canonical sn-* ids", () => {
    expect(isScoreNoteId("sn-000003")).toBe(true);
    expect(isScoreNoteId("sn-000003-2")).toBe(false);
    expect(isScoreNoteId("hs-sn-000003")).toBe(false);
    expect(isScoreNoteId("sn-3")).toBe(false);
    expect(isScoreNoteId("")).toBe(false);
  });

  it("recognizes MusicXML export ids incl. tie fragments", () => {
    expect(isMusicxmlNoteId("hs-sn-000003")).toBe(true);
    expect(isMusicxmlNoteId("hs-sn-000003-2")).toBe(true);
    expect(isMusicxmlNoteId("hs-sn-000003-12")).toBe(true);
    expect(isMusicxmlNoteId("hs-rest-000001")).toBe(false);
    expect(isMusicxmlNoteId("hs-sn-3")).toBe(false);
    expect(isMusicxmlNoteId("sn-000003")).toBe(false);
  });

  it("recognizes rest ids", () => {
    expect(isMusicxmlRestId("hs-rest-000001")).toBe(true);
    expect(isMusicxmlRestId("hs-sn-000001")).toBe(false);
  });

  it("recognizes review issue ids", () => {
    expect(isReviewIssueId("ri-000001")).toBe(true);
    expect(isReviewIssueId("ri-1")).toBe(false);
  });

  it("builds export ids from canonical ids", () => {
    expect(musicxmlNoteId("sn-000042")).toBe("hs-sn-000042");
    expect(musicxmlNoteId("sn-000042", 2)).toBe("hs-sn-000042-2");
    expect(musicxmlNoteId("sn-000042", 3)).toBe("hs-sn-000042-3");
    expect(() => musicxmlNoteId("sn-42")).toThrow();
    expect(() => musicxmlNoteId("sn-000042", 0)).toThrow();
  });

  it("resolves every hs-sn-* fragment to its canonical id", () => {
    expect(canonicalNoteIdFromMusicxml("hs-sn-000003")).toBe("sn-000003");
    expect(canonicalNoteIdFromMusicxml("hs-sn-000003-2")).toBe("sn-000003");
    expect(canonicalNoteIdFromMusicxml("hs-sn-000003-10")).toBe("sn-000003");
  });

  it("rejects non-canonical ids (rests, Verovio random ids)", () => {
    // UI-003 finding: Verovio-generated ids like `d1e123` are unstable —
    // they must never resolve to a canonical note.
    expect(canonicalNoteIdFromMusicxml("hs-rest-000001")).toBeNull();
    expect(canonicalNoteIdFromMusicxml("d1e123")).toBeNull();
    expect(canonicalNoteIdFromMusicxml("hs-sn-3")).toBeNull();
    expect(canonicalNoteIdFromMusicxml("")).toBeNull();
    expect(canonicalNoteIdFromMusicxml("sn-000003")).toBeNull();
  });
});

/**
 * TypeScript mirror of the FND-001 identity rules
 * (`python/hornscribe/domain/ids.py`, `docs/CONTRACTS.md` §1).
 *
 *   canonical note         sn-<6 digits>
 *   MusicXML note/@id      hs-sn-<6 digits>
 *   MusicXML tied fragment hs-sn-<6 digits>-<k>   (k > 1)
 *   MusicXML rest          hs-rest-<6 digits>     (presentation-only)
 *   review issue           ri-<6 digits>
 *
 * Every `hs-sn-*` export id — fragment or not — resolves back to exactly one
 * `sn-*` canonical note id. `hs-rest-*` deliberately has no canonical target.
 * Verified in the UI-003 spike: Verovio mirrors `note/@id` verbatim onto the
 * rendered `<g class="note">`, so a rendered element always resolves to a
 * canonical note.
 */

const SCORE_NOTE_RE = /^sn-\d{6}$/;
const MUSICXML_NOTE_RE = /^hs-sn-\d{6}(?:-\d+)?$/;
const MUSICXML_REST_RE = /^hs-rest-\d{6}$/;
const REVIEW_ISSUE_RE = /^ri-\d{6}$/;
const CANONICAL_PART_RE = /^hs-(sn-\d{6})/;

export function isScoreNoteId(value: string): boolean {
  return SCORE_NOTE_RE.test(value);
}

export function isMusicxmlNoteId(value: string): boolean {
  return MUSICXML_NOTE_RE.test(value);
}

export function isMusicxmlRestId(value: string): boolean {
  return MUSICXML_REST_RE.test(value);
}

export function isReviewIssueId(value: string): boolean {
  return REVIEW_ISSUE_RE.test(value);
}

/** `sn-000042` -> `hs-sn-000042` (fragment 1), `hs-sn-000042-2` (fragment 2), … */
export function musicxmlNoteId(canonicalId: string, fragment = 1): string {
  if (!isScoreNoteId(canonicalId)) {
    throw new Error(`not a canonical score note id: ${canonicalId}`);
  }
  if (fragment < 1) {
    throw new Error(`fragment must be >= 1, got ${fragment}`);
  }
  return fragment === 1 ? `hs-${canonicalId}` : `hs-${canonicalId}-${fragment}`;
}

/**
 * `hs-sn-000042` -> `sn-000042`; `hs-sn-000042-3` -> `sn-000042`.
 * Returns null for anything that is not a canonical-backed export id
 * (e.g. `hs-rest-*`, or a Verovio-generated id like `d1e123` — random ids are
 * never stable, see UI-003 §2).
 */
export function canonicalNoteIdFromMusicxml(exportId: string): string | null {
  if (!isMusicxmlNoteId(exportId)) return null;
  const match = CANONICAL_PART_RE.exec(exportId);
  return match ? match[1] : null;
}

