/**
 * UI-040 → UI-030 handoff adapter.
 *
 * A completed transcription job carries `result` (`unknown`) with
 * `scoreRevision` and `reviewIssues` (sidecar/protocol.ts). This module
 * normalizes that payload into the typed score-side contract:
 *
 * - `scoreRevision` → the document `revisionId` (remount key / identity).
 * - `reviewIssues` → `ScoreReviewIssue[]` — the same ReviewIssue shape the
 *   python domain emits; reason codes stay verbatim (the copy layer falls
 *   back to `reviewReasons.other` for codes newer than the enum).
 *
 * What the result does NOT carry yet is MusicXML — the engine pipeline
 * still owes the real document body. Until then the fixture adapter
 * supplies the notation and only identity + review issues come from the
 * job result. That is deliberately honest: no fake engraving is claimed
 * to be engine output.
 */
import {
  extractReviewIssues,
  REVIEW_ISSUE_STATUSES,
  REVIEW_SEVERITIES,
  type ReviewIssuePayload,
} from "../sidecar/review";
import type {
  ReviewIssueStatus,
  ReviewReason,
  ReviewSeverity,
  ScoreReviewIssue,
} from "./review";

/** Fields the score document takes from a completed job's result. */
export interface ScoreResultHandoff {
  /** `sr-*` revision id, when the engine emitted one. */
  readonly revisionId?: string;
  /** Review issues typed for the score workspace (possibly empty — a
   *  clean transcription honestly reports zero issues). */
  readonly issues: readonly ScoreReviewIssue[];
}

/**
 * Extract the score-facing fields from `session.lastResult`.
 * Returns `undefined` when the payload is not an object at all (e.g. no
 * result was attached) so callers can fall back to fixture defaults; an
 * object without `reviewIssues` yields an empty issue list — the absence
 * of issues is real information, not a fallback case.
 */
export function scoreHandoffFromResult(
  result: unknown,
): ScoreResultHandoff | undefined {
  if (typeof result !== "object" || result === null) return undefined;
  const r = result as Record<string, unknown>;
  return {
    revisionId:
      typeof r.scoreRevision === "string" ? r.scoreRevision : undefined,
    issues: extractReviewIssues(result).map(toScoreIssue),
  };
}

function toScoreIssue(p: ReviewIssuePayload): ScoreReviewIssue {
  return {
    id: p.id,
    scoreRevision:
      typeof p.scoreRevision === "string" ? p.scoreRevision : "",
    canonicalNoteIds: Array.isArray(p.canonicalNoteIds)
      ? p.canonicalNoteIds.filter((id): id is string => typeof id === "string")
      : [],
    timeRange: isTimeRange(p.timeRange) ? p.timeRange : undefined,
    // Verbatim reason code — `ja.reviewReasons.other` covers engine codes
    // this UI version does not know yet (same policy as sidecar/review.ts).
    reason: p.reason as ReviewReason,
    severity: isSeverity(p.severity) ? p.severity : "info",
    evidence: p.evidence ?? {},
    status: isStatus(p.status) ? p.status : "open",
  };
}

function isTimeRange(
  raw: unknown,
): raw is { readonly startSec: number; readonly endSec: number } {
  if (typeof raw !== "object" || raw === null) return false;
  const t = raw as Record<string, unknown>;
  return typeof t.startSec === "number" && typeof t.endSec === "number";
}

function isSeverity(raw: unknown): raw is ReviewSeverity {
  return (
    typeof raw === "string" &&
    (REVIEW_SEVERITIES as readonly string[]).includes(raw)
  );
}

function isStatus(raw: unknown): raw is ReviewIssueStatus {
  return (
    typeof raw === "string" &&
    (REVIEW_ISSUE_STATUSES as readonly string[]).includes(raw)
  );
}

/**
 * Playback-table tests (UI-030). The table precomputes score-ms → sounding
 * canonical notes from Verovio timemap output so the frame pump never calls
 * into WASM (UI-005 finding).
 */
import { describe, expect, it } from "vitest";
import type { VerovioTimemapEntry } from "verovio/esm";
import {
  activeCanonicalsAt,
  buildPlaybackTable,
  canonicalsInRange,
  nearestCanonicalAt,
  segmentAt,
} from "./playbackTable";

/** Fixture-shaped timemap: a melody + a rest gap + a tied note chain. */
const TIMEMAP: VerovioTimemapEntry[] = [
  { qstamp: 0, tstamp: 0, on: ["hs-sn-000001"], off: [] },
  { qstamp: 1, tstamp: 500, on: ["hs-sn-000002"], off: ["hs-sn-000001"] },
  { qstamp: 2, tstamp: 1000, on: ["hs-sn-000003"], off: ["hs-sn-000002"] },
  // rest gap 1500..2000 — nothing sounding
  { qstamp: 3, tstamp: 1500, on: [], off: ["hs-sn-000003"] },
  { qstamp: 4, tstamp: 2000, on: ["hs-sn-000004"], off: [] },
  // tie: fragment 2 takes over while fragment 1 ends — the canonical note
  // keeps sounding across the fragment boundary.
  { qstamp: 5, tstamp: 2500, on: ["hs-sn-000004-2"], off: ["hs-sn-000004"] },
  { qstamp: 6, tstamp: 3000, on: [], off: ["hs-sn-000004-2"] },
];

const table = buildPlaybackTable(TIMEMAP);

describe("buildPlaybackTable", () => {
  it("computes the document duration from the last tstamp", () => {
    expect(table.durationMs).toBe(3000);
  });

  it("maps export ids to their onset ms", () => {
    expect(table.onsetMsByExportId.get("hs-sn-000002")).toBe(500);
    expect(table.onsetMsByExportId.get("hs-sn-000004-2")).toBe(2500);
  });

  it("groups fragments under one canonical id with the earliest onset", () => {
    expect(table.exportIdsByCanonical.get("sn-000004")).toEqual([
      "hs-sn-000004",
      "hs-sn-000004-2",
    ]);
    expect(table.onsetMsByCanonical.get("sn-000004")).toBe(2000);
  });
});

describe("segmentAt", () => {
  it("returns the sounding segment (half-open bounds)", () => {
    expect(segmentAt(table, 0)?.canonicalIds.has("sn-000001")).toBe(true);
    expect(segmentAt(table, 499)?.canonicalIds.has("sn-000001")).toBe(true);
    expect(segmentAt(table, 500)?.canonicalIds.has("sn-000002")).toBe(true);
  });

  it("keeps a tied note sounding across its fragment boundary", () => {
    expect(segmentAt(table, 2400)?.canonicalIds.has("sn-000004")).toBe(true);
    expect(segmentAt(table, 2600)?.canonicalIds.has("sn-000004")).toBe(true);
  });

  it("returns null in rest gaps and after the end", () => {
    expect(segmentAt(table, 1700)).toBeNull();
    expect(segmentAt(table, 3000)).toBeNull();
    expect(activeCanonicalsAt(table, 1700).size).toBe(0);
  });
});

describe("canonicalsInRange", () => {
  it("returns every canonical overlapping the half-open range", () => {
    const set = canonicalsInRange(table, 400, 2100);
    expect(set.has("sn-000001")).toBe(true);
    expect(set.has("sn-000002")).toBe(true);
    expect(set.has("sn-000003")).toBe(true);
    expect(set.has("sn-000004")).toBe(true);
  });

  it("excludes notes that end exactly at the range start", () => {
    const set = canonicalsInRange(table, 500, 600);
    expect(set.has("sn-000001")).toBe(false);
    expect(set.has("sn-000002")).toBe(true);
  });

  it("returns an empty set for empty/inverted ranges", () => {
    expect(canonicalsInRange(table, 100, 100).size).toBe(0);
    expect(canonicalsInRange(table, 200, 100).size).toBe(0);
  });
});

describe("nearestCanonicalAt", () => {
  it("returns the earliest-onset sounding canonical", () => {
    expect(nearestCanonicalAt(table, 100)).toBe("sn-000001");
  });

  it("resolves rest gaps to the nearest onset either side", () => {
    // Gap 1500..2000: sn-000004's onset (2000) is closer than sn-000003's
    // (1000) everywhere inside the gap.
    expect(nearestCanonicalAt(table, 1900)).toBe("sn-000004");
    // Past the document end the scan falls back to the latest onset.
    expect(nearestCanonicalAt(table, 3100)).toBe("sn-000004");
  });
});

/**
 * Precomputed playback-position table (score milliseconds → sounding
 * canonical notes) built once per document load from Verovio's timemap.
 *
 * UI-005 finding: `getElementsAtTime` is onset-exact but costs a WASM call
 * per lookup; the production path precomputes an onset→canonical table so
 * the rAF pump is an array scan / binary search, never a per-frame WASM
 * call and never a re-render.
 */
import type { VerovioTimemapEntry } from "verovio/esm";
import { canonicalNoteIdFromMusicxml } from "./ids";

/** Notes sounding during `[startMs, endMs)` (half-open). */
export interface PlaybackSegment {
  readonly startMs: number;
  readonly endMs: number;
  /** MusicXML export ids (`hs-sn-*`) starting/ending at the boundaries. */
  readonly exportIds: readonly string[];
  /** Resolved canonical `sn-*` ids sounding in this segment. */
  readonly canonicalIds: ReadonlySet<string>;
}

export interface PlaybackTable {
  readonly segments: readonly PlaybackSegment[];
  readonly durationMs: number;
  /** export id → onset ms (first timemap `on` occurrence). */
  readonly onsetMsByExportId: ReadonlyMap<string, number>;
  /** canonical id → onset ms (earliest fragment onset). */
  readonly onsetMsByCanonical: ReadonlyMap<string, number>;
  /** canonical id → export ids (all fragments, in `on` order). */
  readonly exportIdsByCanonical: ReadonlyMap<string, readonly string[]>;
}

/**
 * Build the playback table from `renderToTimemap()` output. Entries are
 * ordered by tstamp; each carries `on`/`off` id lists for that timestamp.
 * A note is "sounding" in segment i when its `on` was applied and its `off`
 * has not yet arrived — `off` is applied before `on` at equal timestamps so
 * a note ending exactly on the boundary does not bleed into the next
 * segment (a tied note's sounding span is covered by its fragments).
 */
export function buildPlaybackTable(timemap: readonly VerovioTimemapEntry[]): PlaybackTable {
  const segments: PlaybackSegment[] = [];
  const sounding = new Set<string>();
  const onsetMsByExportId = new Map<string, number>();
  const fragments = new Map<string, string[]>();

  for (let i = 0; i < timemap.length; i++) {
    const entry = timemap[i];
    for (const id of entry.off ?? []) sounding.delete(id);
    for (const id of entry.on ?? []) {
      sounding.add(id);
      if (!onsetMsByExportId.has(id)) onsetMsByExportId.set(id, entry.tstamp);
      const canonical = canonicalNoteIdFromMusicxml(id);
      if (canonical) {
        const list = fragments.get(canonical) ?? [];
        if (!list.includes(id)) list.push(id);
        fragments.set(canonical, list);
      }
    }
    const next = timemap[i + 1];
    const startMs = entry.tstamp;
    const endMs = next ? next.tstamp : startMs;
    if (sounding.size === 0) continue;
    segments.push({
      startMs,
      endMs,
      exportIds: [...sounding],
      canonicalIds: new Set(
        [...sounding]
          .map((id) => canonicalNoteIdFromMusicxml(id))
          .filter((id): id is string => id !== null),
      ),
    });
  }

  const onsetMsByCanonical = new Map<string, number>();
  for (const [canonicalId, ids] of fragments) {
    let min = Number.POSITIVE_INFINITY;
    for (const id of ids) {
      const t = onsetMsByExportId.get(id);
      if (t !== undefined && t < min) min = t;
    }
    if (Number.isFinite(min)) onsetMsByCanonical.set(canonicalId, min);
  }

  let durationMs = 0;
  for (const entry of timemap) durationMs = Math.max(durationMs, entry.tstamp);

  return {
    segments,
    durationMs,
    onsetMsByExportId,
    onsetMsByCanonical,
    exportIdsByCanonical: fragments,
  };
}

/** Binary search: segment containing `ms`, or null outside the table. */
export function segmentAt(table: PlaybackTable, ms: number): PlaybackSegment | null {
  const segments = table.segments;
  let lo = 0;
  let hi = segments.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const seg = segments[mid];
    if (ms < seg.startMs) hi = mid - 1;
    else if (ms >= seg.endMs) lo = mid + 1;
    else return seg;
  }
  return null;
}

/** Canonical ids sounding at `ms` (empty set during rests/gaps). */
export function activeCanonicalsAt(table: PlaybackTable, ms: number): ReadonlySet<string> {
  return segmentAt(table, ms)?.canonicalIds ?? new Set<string>();
}

/** Canonical ids whose [onset,offset) overlaps `[startMs,endMs)` — used for
 *  the loop-passage mark on the score. Half-open overlap, matching the
 *  UI-005 semantics. */
export function canonicalsInRange(
  table: PlaybackTable,
  startMs: number,
  endMs: number,
): Set<string> {
  const out = new Set<string>();
  if (endMs <= startMs) return out;
  for (const seg of table.segments) {
    if (seg.endMs <= startMs) continue;
    if (seg.startMs >= endMs) break;
    for (const id of seg.canonicalIds) out.add(id);
  }
  return out;
}

/** Nearest canonical onset at-or-after `ms`, falling back to the previous
 *  sounding note when `ms` sits in a rest gap (matches the "nearest-note
 *  resolution" behavior verified in UI-005). */
export function nearestCanonicalAt(table: PlaybackTable, ms: number): string | null {
  const seg = segmentAt(table, ms);
  if (seg && seg.canonicalIds.size > 0) {
    // Deterministic: lowest onset first.
    let best: string | null = null;
    let bestOnset = Number.POSITIVE_INFINITY;
    for (const id of seg.canonicalIds) {
      const onset = table.onsetMsByCanonical.get(id) ?? Number.POSITIVE_INFINITY;
      if (onset < bestOnset) {
        bestOnset = onset;
        best = id;
      }
    }
    if (best) return best;
  }
  // Gap (rest): scan for the nearest onset either side.
  let bestId: string | null = null;
  let bestDist = Number.POSITIVE_INFINITY;
  for (const [id, onset] of table.onsetMsByCanonical) {
    const d = Math.abs(onset - ms);
    if (d < bestDist) {
      bestDist = d;
      bestId = id;
    }
  }
  return bestId;
}

/**
 * Review-issue model — TypeScript mirror of
 * `python/hornscribe/domain/review.py` (MASTER_PLAN §10).
 *
 * The engine converts backend-specific evidence into product-level review
 * items; the UI consumes the reason code and maps it to Japanese copy — it
 * never interprets raw backend confidence as a universal probability.
 */

/** Engine-side reason codes (stable API; keep in sync with ReviewReason). */
export type ReviewReason =
  | "low_model_confidence"
  | "very_short_detection"
  | "overlapping_candidates"
  | "quantization_ambiguous"
  | "pitch_spelling_ambiguous"
  | "outside_preferred_horn_range"
  | "structural_measure_conflict";

export type ReviewSeverity = "info" | "caution" | "warning";
export type ReviewIssueStatus = "open" | "accepted" | "dismissed" | "fixed";

export interface ScoreReviewIssue {
  /** `ri-<6 digits>`, allocated deterministically within one score revision. */
  readonly id: string;
  readonly scoreRevision: string;
  /** Canonical `sn-*` ids this issue points at (1+). */
  readonly canonicalNoteIds: readonly string[];
  readonly timeRange?: { readonly startSec: number; readonly endSec: number };
  readonly reason: ReviewReason;
  readonly severity: ReviewSeverity;
  /** Engine evidence payload (e.g. `{ confidence: 0.62 }`); never shown raw. */
  readonly evidence: Readonly<Record<string, unknown>>;
  readonly status: ReviewIssueStatus;
}

/** Issues still needing user attention. */
export function openIssues(issues: readonly ScoreReviewIssue[]): ScoreReviewIssue[] {
  return issues.filter((i) => i.status === "open");
}

/** All open issues touching `canonicalId` (a note can carry several). */
export function issuesForCanonical(
  issues: readonly ScoreReviewIssue[],
  canonicalId: string,
): ScoreReviewIssue[] {
  return issues.filter(
    (i) => i.status === "open" && i.canonicalNoteIds.includes(canonicalId),
  );
}

/** Canonical ids carrying at least one open issue — drives score markers. */
export function markedCanonicalIds(issues: readonly ScoreReviewIssue[]): Set<string> {
  const out = new Set<string>();
  for (const issue of openIssues(issues)) {
    for (const id of issue.canonicalNoteIds) out.add(id);
  }
  return out;
}

/** Optional model confidence from the evidence payload (0..1), or null.
 *  Surfaced in the inspector as evidence only — never as "probability of
 *  being wrong" (GUI_UX_PLAN §21). The engine emits `modelConfidence`
 *  (sidecar ReviewIssue dicts); `confidence` is accepted for older
 *  payloads. */
export function issueConfidence(issue: ScoreReviewIssue): number | null {
  for (const key of ["confidence", "modelConfidence"] as const) {
    const value = issue.evidence[key];
    if (typeof value === "number" && Number.isFinite(value)) return value;
  }
  return null;
}

